#!/usr/bin/env python3
# Parallel live-oracle prober. Spawns one isolated challenge pd instance per probe on its own
# port (bindshim remap), drives CUE/SYNC/EQ/KEY/DECK/EXPORT, captures the 42-char render.
# ANSWER-AGNOSTIC: no answer knowledge; just relays the console and returns the raw render.
import socket, time, threading, subprocess, os, sys, re, signal

LAUNCH = "/home/vboxuser/rev-analysis/work/myrun/launch_mine.sh"
CHK = "L7USw*KLz'0VI/3)keO#]_}z\":M$tYIFf-HB'c8NwU"

def _recv_until(sock, needle, maxwait, buf):
    t0=time.time()
    while time.time()-t0<maxwait:
        try:
            d=sock.recv(65536)
            if not d: break
            buf.extend(d)
            if needle in buf and (time.time()-t0)>0.1:
                return True
        except socket.timeout:
            if needle in buf: return True
        except Exception:
            break
    return needle in buf

def start_instance(port, logdir):
    env=dict(os.environ)
    env["REMAP"]=str(port)
    env["LD_LIBRARY_PATH"]="/usr/lib/x86_64-linux-gnu:/opt/purr-data/lib/pd-l2ork/bin:/opt/purr-data/lib"
    log=open(os.path.join(logdir, f"pd_{port}.log"),"wb")
    p=subprocess.Popen(["bash",LAUNCH], env=env, stdout=log, stderr=subprocess.STDOUT,
                        preexec_fn=os.setsid)
    return p

def wait_listen(port, maxwait=40):
    t0=time.time()
    while time.time()-t0<maxwait:
        try:
            s=socket.create_connection(("127.0.0.1",port),timeout=1.0)
            s.close(); return True
        except Exception:
            time.sleep(0.4)
    return False

def kill_instance(p):
    try:
        os.killpg(os.getpgid(p.pid), signal.SIGKILL)
    except Exception:
        try: p.kill()
        except Exception: pass

def extract_render(text):
    # the render line after "rendering stem ...\n\n"
    m=re.search(r'rendering stem \.\.\.\n\n(.*?)\n', text, re.S)
    if m: return m.group(1)
    return None

def probe(port, key, arg, logdir="/home/vboxuser/rev-analysis/work/myrun/plogs",
          init_wait=3.5, verbose=False):
    os.makedirs(logdir, exist_ok=True)
    p=start_instance(port, logdir)
    try:
        if not wait_listen(port):
            return {"ok":False,"err":"no_listen","key":key,"arg":arg}
        time.sleep(init_wait)
        s=socket.create_connection(("127.0.0.1",port),timeout=10); s.settimeout(1.0)
        buf=bytearray()
        seq=[("CUE IKOW[g",8),("SYNC",8),("EQ music'_'",8),(f"KEY {key}",10),("DECK",8)]
        for cmd,to in seq:
            s.sendall((cmd+"\n").encode('latin1'))
            _recv_until(s,b"CSIRAC> ",to,buf)
            buf.clear()
        # EXPORT
        s.sendall((f"EXPORT {arg}\n").encode('latin1'))
        got=_recv_until(s,b"CSIRAC> ",40,buf)
        text=buf.decode('latin1')
        s.close()
        render=extract_render(text)
        res={"ok":render is not None,"key":key,"arg":arg,"render":render,
             "is_checkpoint": (render==CHK) if render else False,
             "raw": text if verbose else None}
